corrected_code:
const grpc = require('@grpc/grpc-js');
const db = require('../db');

function getInvoicePdf(call, callback) {
  const invoiceId = call.request.invoice_id;
  const tenantId = call.metadata.get('x-tenant-id')[0];

  if (!invoiceId) {
    return callback({ code: grpc.status.INVALID_ARGUMENT, message: 'Missing invoice_id' });
  }

  if (!tenantId) {
    return callback({ code: grpc.status.UNAUTHENTICATED, message: 'Missing tenant metadata' });
  }

  // Scopes lookup strictly to the requesting tenantId forwarded by Envoy
  db.collection('invoices').findOne({ _id: invoiceId, tenant_id: tenantId }, (err, invoice) => {
    if (err || !invoice) {
      return callback({ code: grpc.status.NOT_FOUND, message: 'Invoice not found or access denied' });
    }

    callback(null, {
      invoice_id: invoice._id,
      pdf_blob: invoice.pdf_data,
      total_cents: invoice.total_cents,
      currency: invoice.currency
    });
  });
}

module.exports = { getInvoicePdf };
